use vstd::prelude::*;

verus! {

/// Returns a fresh vector with exactly the same elements (same order) as `a`.
///
/// The input `a` is not modified (it is borrowed immutably), and the result
/// matches `a` element-wise and in length.
fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        // Same length
        result.len() == a.len(),
        // Element-wise equality for all valid indices
        forall|i: int| 0 <= i && i < a.len() ==> result[i] == a[i],
        // Convenient sequence view equality (implied by the above, but useful)
        result@ == a@,
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            0 <= i as int <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j && j < i as int ==> result[j] == a[j],
            result@ == a@.subrange(0, i as int),
    {
        result.push(a[i]);
        i += 1;
    }

    result
}

} // verus!